-- Migration 020: Fix pharmacy_stock schema and seed inventory data
-- Old pharmacy_stock had wrong columns; recreate with correct schema and seed all 216 taxonomy items.

drop policy if exists "Authenticated read pharmacy_stock" on pharmacy_stock;
drop index if exists idx_pharmacy_stock_facility;
drop index if exists idx_pharmacy_stock_medication;
drop table pharmacy_stock;

create table pharmacy_stock (
  id text primary key,
  facility_id integer not null references facilities(id),
  medication_name text not null,
  generic_name text,
  brand_name text,
  unit_price numeric not null,
  in_stock boolean not null default true,
  quantity_available integer not null default 0,
  last_restocked_at timestamptz,
  updated_at timestamptz default now()
);

create index idx_pharmacy_stock_facility on pharmacy_stock(facility_id);
create index idx_pharmacy_stock_medication on pharmacy_stock(medication_name);
create index idx_pharmacy_stock_generic on pharmacy_stock(generic_name);

alter table pharmacy_stock enable row level security;
create policy "Authenticated read pharmacy_stock" on pharmacy_stock
  for select using (auth.role() = 'authenticated');


